// SKELETON (DEVDESK-753, red phase, lot 1). Every symbol below is a stub, kept
// just large enough for the tests to compile and fail on their assertions. The
// coder replaces the bodies; nothing here is the design.
//
// Skeleton symbols: misconfigChange, misconfigChangeOf, changeLines,
// computeMisconfigFix (today's body of prepareMisconfigFixCmd, moved as it was),
// previewStale, reasonPreviewStale, previewFailure.

// reasonPreviewStale is why a fix is refused on a file written after the scan.
const reasonPreviewStale = "SKELETON"

// misconfigChange is the fix as it would land: the pure product shared by the
// preview and ctrl+o.
type misconfigChange struct {
	// File is the slash path, relative to the target, of the file the fix edits.
	File string
	// Lines is the formatted diff, sanitized, uncapped and uncut.
	Lines []string
	// Updated is the exact bytes ctrl+o writes.
	Updated []byte
	Scope   remediation.Scope
}

// misconfigChangeOf is the pure part of the computation: no I/O. It returns a
// reason when the rule declines.
func misconfigChangeOf(rule remediation.Rule, rel string, original []byte, f scan.Finding) (misconfigChange, string, error) {
	return misconfigChange{}, "", nil
}

// changeLines formats a patch.Diff for display.
func changeLines(diff string) []string { return nil }

// previewStale says whether a file written at modTime changed after the scan.
func previewStale(modTime, scannedAt time.Time) bool { return false }

// previewFailure words an error without ever showing err.Error().
func previewFailure(rel string, err error) string { return "" }

// computeMisconfigFix is the body prepareMisconfigFixCmd had before this ticket.
func computeMisconfigFix(target string, f scan.Finding, _ time.Time) MisconfigFixPreparedMsg {
	rule, ok := remediation.FixFor(f)
	if !ok {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{noFixReason(f)}}
	}
	rel, reason := rule.FileFor(target, f)
	if reason != "" {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
	}
	path := filepath.Join(target, filepath.FromSlash(rel))
	original, err := readFile(path)
	if err != nil {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
	}
	edits, reason := rule.Fix(original, f)
	if reason != "" {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
	}
	updated, err := patch.Rewrite(original, edits)
	if err != nil {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
	}
	diff, err := patch.Diff(rel, original, edits)
	if err != nil {
		return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
	}
	file := preparedWrite{File: rel, Path: path, Original: original, Updated: updated}
	if file.State, err = git.StateOf(path); err != nil {
		log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
		file.StateErr = true
	}
	body := rule.Title + "\n\n"
	if rule.Warning != "" {
		body += "Warning: " + rule.Warning + "\n\n"
	}
	return MisconfigFixPreparedMsg{
		Target: target, File: file, FindingFile: f.File,
		Rule: f.ID, Instance: instanceOf(f), Body: body + diff,
		Scope: rule.ScopeOf(updated, edits),
	}
}
