321				// The text handed to the modal is the body of the preparation.
322				if want := misconfigConfirmationText(msg.File, msg.Body); !strings.Contains(want, strings.Join(msg.Lines, "\n")) {
323					t.Errorf("the confirmation text does not hold the lines joined by newlines:\n%s", want)
324				}
325				if got := readTree(t, dir, fx.edited); got != fx.files[fx.edited] {
326					t.Fatalf("the file was written before the answer:\n%s", got)
327				}
328	
329				// Yes: the write is the one the modal was about.
330				m, cmd := step(t, m, sharedcomponents.ConfirmModalYesMsg{})
331				written, ok := run(t, cmd).(MisconfigFixWrittenMsg)
332				if !ok || written.Err != nil {
333					t.Fatalf("the write failed: %+v", written)
334				}
335				_ = feed(t, m, written)
336				if got := readTree(t, dir, fx.edited); got != string(msg.File.Updated) {
337					t.Errorf("the file on disk is not Updated:\n got: %q\nwant: %q", got, msg.File.Updated)
338				}
339				// And it is what the catalog's rewrite gives, computed here on its own.
340				edits, _ := ruleOf(t, fx).Fix([]byte(fx.files[fx.edited]), fx.finding)
341				want, err := patch.Rewrite([]byte(fx.files[fx.edited]), edits)
342				if err != nil || readTree(t, dir, fx.edited) != string(want) {
343					t.Errorf("the file on disk is not patch.Rewrite of the original (err %v)", err)
344				}
345			})
346		}
347	}
