476		if got := previewFailure(rel, errors.New(secret)); got != "the fix could not be computed — check logs" {
477			t.Errorf("other: %q", got)
478		}
479		// A wrapped error is still classified.
480		wrapped := errors.Join(errors.New("context"), &fs.PathError{Op: "stat", Path: rel, Err: fs.ErrPermission})
481		if got := previewFailure(rel, wrapped); got != rel+" cannot be read" {
482			t.Errorf("wrapped permission: %q", got)
483		}
484	}
