112	// AC1: the product is not capped and not cut. The section shows the first lines
113	// and says how many more; the product itself keeps them all.
114	func TestChangeLinesKeepsEveryLineAndEveryCell(t *testing.T) {
115		long := strings.Repeat("x", 600)
116		var b strings.Builder
117		b.WriteString("--- f\n+++ f\n")
118		for i := 1; i <= 120; i++ {
119			b.WriteString("@@ line 1 @@\n+" + long + "\n")
120		}
121		got := changeLines(b.String())
122		if len(got) != 240 {
123			t.Fatalf("%d lines, want 240", len(got))
124		}
125		for _, l := range got {
126			if strings.HasPrefix(l, "+") && l != "+"+long {
127				t.Fatalf("a line was cut to %d cells", len(l))
128			}
129		}
130	}
