269	// diffRows counts the lines that read as part of a diff.
270	func diffRows(lines []string) int {
271		n := 0
272		for _, l := range lines {
273			if strings.HasPrefix(l, "+") || strings.HasPrefix(l, "-") || strings.HasPrefix(l, "  @@") {
274				n++
275			}
276		}
277		return n
278	}
279	
280	// indexOfBlock is where block starts in lines, or -1.
281	func indexOfBlock(lines, block []string) int {
282		for i := 0; i+len(block) <= len(lines); i++ {
283			if slices.Equal(lines[i:i+len(block)], block) {
284				return i
285			}
286		}
287		return -1
288	}
