290	// For every rule of the catalog: the text of the modal holds exactly the lines
291	// of the preview, then the file and its git advice; and once the answer is yes,
292	// the bytes on disk are the bytes the preview was computed with.
293	func TestTheModalShowsExactlyThePreviewLinesAndTheFileWrittenIsUpdated(t *testing.T) {
294		for _, fx := range changeFixtures(t) {
