298	
299				m, msg := previewed(t, m)
300				if m.confirmModal == nil {
301					t.Fatalf("no confirmation opened; footer: %q", m.footer.Text())
302				}
303				if len(msg.Lines) == 0 {
304					t.Fatal("the preparation produced no preview line")
305				}
306	
307				rows := modalLines(m)
308				at := indexOfBlock(rows, msg.Lines)
309				if at < 0 {
310					t.Fatalf("the modal does not hold the preview lines:\n%q\nmodal:\n%s", msg.Lines, strings.Join(rows, "\n"))
311				}
312				if got, want := diffRows(rows), len(msg.Lines); got != want {
313					t.Errorf("the modal has %d diff rows, the preview %d: something else is shown as a change", got, want)
314				}
315				// The file and its git advice follow the lines, as before (modalLines
316				// leaves the blank rows out).
317				tail := rows[at+len(msg.Lines):]
318				if len(tail) == 0 || !strings.HasPrefix(tail[0], fx.edited+": ") {
319					t.Errorf("after the lines, the modal reads %q; want %q", tail, fx.edited+": <git advice>")
320				}
