15	
16	func TestCatalogIDsListsEveryRuleOfTheCatalogOnce(t *testing.T) {
17		ids := CatalogIDs()
18		if len(ids) == 0 {
19			t.Fatal("CatalogIDs is empty")
20		}
21		if len(ids) != len(catalog) {
22			t.Errorf("CatalogIDs lists %d ids, the catalog holds %d rules", len(ids), len(catalog))
23		}
24		seen := map[string]bool{}
25		for _, id := range ids {
26			if seen[id] {
27				t.Errorf("%q is listed twice", id)
28			}
29			seen[id] = true
30		}
31	}
