33	func TestCatalogIDsAreSorted(t *testing.T) {
34		ids := CatalogIDs()
35		if len(ids) == 0 {
36			t.Fatal("CatalogIDs is empty")
37		}
38		if !slices.IsSorted(ids) {
39			t.Errorf("CatalogIDs is not sorted: %v", ids)
40		}
