43	// An id the list returns is one FixFor accepts: it is the AVD id of the rule, not
44	// a map key in another spelling.
45	func TestEveryCatalogIDFindsItsRule(t *testing.T) {
46		if len(CatalogIDs()) == 0 {
47			t.Fatal("CatalogIDs is empty")
48		}
49		for _, id := range CatalogIDs() {
50			rule, ok := FixFor(scan.Finding{ID: id, Source: scan.SourceTrivyMisconfig})
51			if !ok {
52				// The two ids DevDesk emits itself come from another source.
53				rule, ok = FixFor(scan.Finding{ID: id, Source: scan.SourceBuildContext})
54			}
55			if !ok {
56				rule, ok = FixFor(scan.Finding{ID: id, Source: scan.SourceKubeconform})
57			}
58			if !ok {
59				t.Errorf("FixFor finds no rule for %q", id)
60				continue
61			}
62			if RuleKey(rule.AVDID) != RuleKey(id) {
63				t.Errorf("%q found the rule %q", id, rule.AVDID)
64			}
65		}
66	}
