68	// The list is a copy: a caller that sorts or edits it cannot reorder the next one.
69	func TestCatalogIDsReturnsACopy(t *testing.T) {
70		first := CatalogIDs()
71		if len(first) == 0 {
72			t.Fatal("CatalogIDs is empty")
73		}
74		want := first[0]
75		first[0] = "changed"
76		if got := CatalogIDs()[0]; got != want {
77			t.Errorf("the second call starts with %q, want %q", got, want)
78		}
79	}
